pub struct Stack<T> {
    items: Vec<T>,
}

impl<T> Stack<T> {
    pub fn new() -> Self {
        Stack { items: Vec::new() }
    }

    pub fn push(&mut self, val: T) {
        self.items.push(val);
    }

    pub fn pop(&mut self) -> Option<T> {
        if self.items.is_empty() {
            return None;
        }
        Some(self.items.remove(0)) // BUG 1: removes from front (FIFO), should be self.items.pop()
    }

    pub fn peek(&self) -> Option<&T> {
        self.items.first() // BUG 2: returns oldest (bottom), should be self.items.last()
    }

    pub fn size(&self) -> usize {
        self.items.len() + 1 // BUG 3: off by one
    }

    pub fn is_empty(&self) -> bool {
        self.items.is_empty()
    }
}

