use generic_stack::Stack;

#[test]
fn test_lifo_order() {
    let mut s: Stack<i32> = Stack::new();
    s.push(1);
    s.push(2);
    s.push(3);
    assert_eq!(s.pop(), Some(3));
    assert_eq!(s.pop(), Some(2));
    assert_eq!(s.pop(), Some(1));
    assert_eq!(s.pop(), None);
}

#[test]
fn test_peek() {
    let mut s: Stack<i32> = Stack::new();
    s.push(5);
    s.push(10);
    assert_eq!(s.peek(), Some(&10)); // peek shows top (last pushed)
    assert_eq!(s.size(), 2);         // peek is non-destructive
}

#[test]
fn test_size_and_empty() {
    let mut s: Stack<i32> = Stack::new();
    assert!(s.is_empty());
    assert_eq!(s.size(), 0);
    s.push(42);
    s.push(99);
    s.push(7);
    assert_eq!(s.size(), 3);
    assert!(!s.is_empty());
}
